INSERT INTO verticalizzazioniparametribase(modulo, parametro, descrizione) VALUES('PROTOCOLLO_URBI', 'ATTIVA_FASC_CONTESTUALE','Attiva la fascicolazione contestualmente alla protocollazione in un''unica chiamata solo per le protocollazioni da movimento. Da utilizzare nei casi in cui nel protocollo urbi siano state attivate delle configurazioni che rendano necessari i dati di fascicolazione contestualmente alla protocollazione in partenza come ad esempio avviente all''ente ATO Monza. Il componente è compatibile con il parametro GESTISCI_FASCICOLAZIONE della regola PROTOCOLLO_ATTIVO. Attivandolo, in fase di protocollazione da un movimento, il componente andrà a recuperare il dato relativo al fascicolo andando a rileggere il protocollo dell''istanza da dove riesce a ricavare il codice del fascicolo che verrà poi utilizzato, se non presente non sarà possibile protocollare in partenza mentre in arrivo si (anche se verranno visualizzati dei warnings), ovviamente l''istanza dovrà avere i riferimenti di protocollazione. Non utilizzare tale configurazione se l''ente prevede di utilizzare la protocollazione per bollettazioni');
