INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_JIRIDE', 'TIPO_ASSEGNAZIONE_COPIA_DEF', 'Impostare il valore che si desidera utilizzare per definire che tipo di assegnazione deve essere effettuata per la creazione di una copia, utilizzata soprattutto in ambito di protocollazione interna con più destinatari. I valore che possono essere indicati sono: COMPETENZA e CONOSCENZA, se non indicato niente o se verrà indicata una stringa non corretta (attenzione, va scritto in maiuscolo), di default verrà applicato il valore CONOSCENZA.');
INSERT INTO verticalizzazioniparametribase (MODULO, PARAMETRO, DESCRIZIONE) VALUES('COMPORTAMENTI_MERCATI','CHIUS_GG_MERC_CHECK_GG_PREC','Alla chiusura della giornata di mercato decide se effettuare il controllo di chiusura delle giornate precedenti. Valori ammessi <b>S / N</b>, Valore predefinito <b>S</b>');
